<section class="dashboard-content"><div class="dashboard-heading"><div><div class="eyebrow">ارتباط مستقیم</div><h1>پیام‌ها</h1></div></div><section class="dash-card"><div class="message-list"><?php foreach($messages as $m):?><article class="proposal-row"><div><strong><?=e($m['sender_name']?:'کاربر')?></strong><p><?=e($m['content'])?></p><small><?=e($m['created_at'])?></small></div></article><?php endforeach;?><?php if(!$messages):?><div class="empty-state">هنوز پیامی ندارید.</div><?php endif;?></div><form class="message-compose" method="post" action="<?=url('/messages/send')?>"><?=csrf_field()?><input type="number" name="receiver_id" required placeholder="شناسه گیرنده"><textarea name="content" required placeholder="پیام خود را بنویسید..."></textarea><button class="button" type="submit">ارسال پیام</button></form></section></section>